package com.empcontrol.agent.metrics;
import org.bukkit.*; import org.bukkit.entity.Player; import org.bukkit.plugin.Plugin; import java.lang.management.*; import java.util.*; import java.util.stream.Collectors;
public final class MetricsCollector { private final Plugin plugin; private final long started = System.currentTimeMillis(); private int joins; private int leaves; public MetricsCollector(Plugin plugin){this.plugin=plugin;} public void joined(){joins++;} public void left(){leaves++;}
  public Map<String,Object> snapshot(boolean connected, int reconnects, int queueSize, int failed) { Runtime rt=Runtime.getRuntime(); double[] tps=Bukkit.getTPS(); List<Map<String,Object>> worlds=Bukkit.getWorlds().stream().map(w -> Map.<String,Object>of("name",w.getName(),"loadedChunks",w.getLoadedChunks().length,"entities",w.getEntities().size(),"tileEntities",w.getTileEntities().size(),"time",w.getTime(),"weather",w.hasStorm()?"STORM":"CLEAR","difficulty",w.getDifficulty().name())).toList(); List<Player> players=new ArrayList<>(Bukkit.getOnlinePlayers()); long used=rt.totalMemory()-rt.freeMemory(), max=rt.maxMemory(); ThreadMXBean threads=ManagementFactory.getThreadMXBean(); long gcCount=0,gcTime=0; for(GarbageCollectorMXBean gc:ManagementFactory.getGarbageCollectorMXBeans()){ if(gc.getCollectionCount()>0)gcCount+=gc.getCollectionCount(); if(gc.getCollectionTime()>0)gcTime+=gc.getCollectionTime(); }
    return Map.of("health", Map.of("online",true,"uptimeMs",System.currentTimeMillis()-started,"tps1m",tps.length>0?tps[0]:20.0,"tps5m",tps.length>1?tps[1]:20.0,"tps15m",tps.length>2?tps[2]:20.0,"msptAverage",Bukkit.getAverageTickTime(),"msptMax",Bukkit.getAverageTickTime(),"tickHealth",Bukkit.getAverageTickTime()>50?"DEGRADED":"HEALTHY","serverVersion",Bukkit.getVersion(),"javaVersion",System.getProperty("java.version"),"paperVersion",Bukkit.getMinecraftVersion(),"pluginVersion",plugin.getDescription().getVersion(),"worldCount",worlds.size()), "performance", Map.of("ramUsed",used,"ramMax",max,"ramPercentage",max==0?0:(used*100.0/max),"systemLoad",ManagementFactory.getOperatingSystemMXBean().getSystemLoadAverage(),"gcCount",gcCount,"gcTimeMs",gcTime,"threadCount",threads.getThreadCount()), "players", Map.of("online",players.size(),"max",Bukkit.getMaxPlayers(),"uniqueSinceStartup",players.stream().map(Player::getUniqueId).distinct().count(),"joinCount",joins,"leaveCount",leaves,"pingList",players.stream().map(p->Map.of("name",p.getName(),"uuid",p.getUniqueId().toString(),"ping",p.getPing(),"world",p.getWorld().getName())).toList(),"opPlayers",Bukkit.getOperators().stream().map(o->Map.of("name",String.valueOf(o.getName()),"uuid",o.getUniqueId().toString())).toList()), "worlds", worlds, "network", Map.of("connectedToApi",connected,"lastHeartbeat",System.currentTimeMillis(),"reconnectCount",reconnects,"pendingEventQueueSize",queueSize,"failedEventDeliveryCount",failed), "security", Map.of("panicMode",false,"agentIntegrityStatus","MVP_SIGNED_MESSAGES")); }
}
